head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf15301";
scwin.dmenus = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_otherwise_32", fn: function(){ return (!(((dma_splitMergeVO.get("bndMergeObjTpCd") ?? (() => { throw new Error("unresolved:" + "splitMergeVO.bndMergeObjTpCd"); })()) === '1'))); } }, { id: "c_when_79", fn: function(){ return ((dma_splitMergeVO.get("bndMergeObjTpCd") ?? (() => { throw new Error("unresolved:" + "splitMergeVO.bndMergeObjTpCd"); })()) === '1'); } }, { id: "c_otherwise_84", fn: function(){ return (!(((dma_splitMergeVO.get("bndMergeObjTpCd") ?? (() => { throw new Error("unresolved:" + "splitMergeVO.bndMergeObjTpCd"); })()) === '1'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

try { scwin.dmenus ={
        "bmenu":2
        ,"mmenu":9
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf15301' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf15301.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_save_onclick
 * @description btn_save 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_save_onclick = async function(e){
    try {
        await scwin.save()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf15301.btn_save_onclick' }); }
};

/**
 * @method
 * @name btn_close_onclick
 * @description btn_close 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf15301.btn_close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_save
 * @description save 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_save = async function () {
    const sbmOptions = {
        id: "tx_fn_save",
        method: "post",
        action: "/company/company.do?method=saveSplitAppl",
        ref: "dma_saveReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function () {
    if (!await scwin.checkData()) {
        return;
    } else {
        if (!await $c.win.confirm("신청하시겠습니까?")) {
            return false;
        }
    }
    const fm = (document.SendForm || { elements: [] });
    fm.action = '/company/company.do?method=saveSplitAppl';
    await scwin.tx_fn_save();
};

/**
 * @method
 * @name checkData
 * @description check Data 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkData = async function () {
    const fm = (document.SendForm || { elements: [] });
    if ($c.str.getByteLength($c.util.getComponent('ipt_applIsuNm').getValue()) === 0) {
        await $c.win.alert("한글종목명을 입력하십시오.");
        $c.util.getComponent("ipt_applIsuNm").focus();
        return false;
    } else {
        if ($c.str.getByteLength($c.util.getComponent('ipt_applIsuEngNm').getValue()) === 0) {
            await $c.win.alert("영문종목명을 입력하십시오.");
            $c.util.getComponent("ipt_applIsuEngNm").focus();
            return false;
        } else {
            if ($c.util.getComponent('dma_saveReq').get('bndMergeObjTpCd')!== "1" && $c.str.getByteLength($c.util.getComponent('ipt_splitRtoContn').getValue()) === 0) {
                await $c.win.alert("분할비율을 확인하십시오.");
                $c.util.getComponent("ipt_splitRtoContn").focus();
                return false;
            } else {
                if ($c.util.getComponent('dma_saveReq').get('bndMergeObjTpCd')!== "1" && (!Chk_Digit_Point($c.util.getComponent('ipt_splitRtoContn').getValue()) || $c.util.getComponent('ipt_splitRtoContn').getValue()>= 100)) {
                    await $c.win.alert("분할비율을 확인하십시오.");
                    $c.util.getComponent("ipt_splitRtoContn").focus();
                    return false;
                }
            }
        }
    }
    return true;
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};
